 const edges=[{a:{x:cx-hw,z:cz-hd},b:{x:cx+hw,z:cz-hd}},{a:{x:cx+hw,z:cz-hd},b:{x:cx+hw,z:cz+hd}},{a:{x:cx+hw,z:cz+hd},b:{x:cx-hw,z:cz+hd}},{a:{x:cx-hw,z:cz+hd},b:{x:cx-hw,z:cz-hd}}];
 const samplesPer=8,reach=1.8;let covered=0,total=0;
 for(const e of edges){for(let i=0;i<=samplesPer;i++){const t=i/samplesPer,p={x:e.a.x+(e.b.x-e.a.x)*t,z:e.a.z+(e.b.z-e.a.z)*t};total++;if(items.some(a=>assetReach(a,p)<reach))covered++;}}
